-- VIEW: vue_admin_joueurs
DROP VIEW IF EXISTS public.vue_admin_joueurs CASCADE;\nCREATE OR REPLACE VIEW public.vue_admin_joueurs AS
 SELECT pr.id AS joueur_id,
    pr.username,
    pr.email,
    pr.nom_affichage,
    pr.role,
    pr.is_active,
    pr.created_at AS compte_cree_le,
    count(p.id) FILTER (WHERE p.est_actif = true AND p.est_mort = false) AS nb_personnages_actifs,
    count(p.id) FILTER (WHERE p.est_mort = true) AS nb_personnages_morts,
    count(p.id) FILTER (WHERE p.est_actif = false) AS nb_personnages_archives,
    count(p.id) AS nb_personnages_total,
    ( SELECT p2.nom
           FROM personnages p2
          WHERE p2.joueur_id = pr.id AND p2.est_actif = true AND p2.est_mort = false
          ORDER BY p2.created_at DESC NULLS LAST
         LIMIT 1) AS personnage_actif_principal
   FROM profiles pr
     LEFT JOIN personnages p ON p.joueur_id = pr.id
  GROUP BY pr.id, pr.username, pr.email, pr.nom_affichage, pr.role, pr.is_active, pr.created_at
  ORDER BY pr.nom_affichage;

-- VIEW: vue_artisanat_etat
DROP VIEW IF EXISTS public.vue_artisanat_etat CASCADE;\nCREATE OR REPLACE VIEW public.vue_artisanat_etat AS
 SELECT vpe.personnage_id,
    vpe.niveau_alchimie,
    vpe.niveau_forge,
    vpe.niveau_joaillerie,
    vpe.niveau_runes,
    p.a_forge_legendaire,
    p.a_joaillerie_legendaire
   FROM vue_personnage_etat vpe
     JOIN personnages p ON p.id = vpe.personnage_id;

-- VIEW: vue_artisanat_quotas
DROP VIEW IF EXISTS public.vue_artisanat_quotas CASCADE;\nCREATE OR REPLACE VIEW public.vue_artisanat_quotas AS
 SELECT personnage_id,
    niveau_alchimie,
    niveau_forge,
    niveau_joaillerie,
    niveau_runes,
    a_forge_legendaire,
    a_joaillerie_legendaire,
        CASE
            WHEN niveau_alchimie >= 3 THEN 12
            WHEN niveau_alchimie >= 2 THEN 9
            WHEN niveau_alchimie >= 1 THEN 5
            ELSE 0
        END AS quota_recettes_total,
        CASE
            WHEN niveau_runes >= 3 THEN 5
            WHEN niveau_runes >= 2 THEN 4
            WHEN niveau_runes >= 1 THEN 2
            ELSE 0
        END AS quota_assemblages_total,
        CASE
            WHEN niveau_alchimie >= 1 THEN 5
            ELSE 0
        END AS quota_alchimie_mineure_total,
        CASE
            WHEN niveau_alchimie >= 2 THEN 4
            ELSE 0
        END AS quota_alchimie_intermediaire_total,
        CASE
            WHEN niveau_alchimie >= 3 THEN 3
            ELSE 0
        END AS quota_alchimie_majeure_total,
    COALESCE(( SELECT count(*)::integer AS count
           FROM personnage_recettes pr
             JOIN recettes_alchimie ra ON ra.id = pr.recette_id
          WHERE pr.personnage_id = e.personnage_id AND pr.est_gratuit = true AND ra.niveau_requis = 1), 0) AS quota_alchimie_mineure_utilises,
    COALESCE(( SELECT count(*)::integer AS count
           FROM personnage_recettes pr
             JOIN recettes_alchimie ra ON ra.id = pr.recette_id
          WHERE pr.personnage_id = e.personnage_id AND pr.est_gratuit = true AND ra.niveau_requis = 2), 0) AS quota_alchimie_intermediaire_utilises,
    COALESCE(( SELECT count(*)::integer AS count
           FROM personnage_recettes pr
             JOIN recettes_alchimie ra ON ra.id = pr.recette_id
          WHERE pr.personnage_id = e.personnage_id AND pr.est_gratuit = true AND ra.niveau_requis = 3), 0) AS quota_alchimie_majeure_utilises,
    COALESCE(( SELECT count(*)::integer AS count
           FROM personnage_assemblages pa
          WHERE pa.personnage_id = e.personnage_id AND pa.est_gratuit = true), 0) AS quota_assemblages_utilises
   FROM vue_artisanat_etat e;

-- VIEW: vue_cercles_disponibles
DROP VIEW IF EXISTS public.vue_cercles_disponibles CASCADE;\nCREATE OR REPLACE VIEW public.vue_cercles_disponibles AS
 SELECT pc.personnage_id,
    pc.choix_achat AS cercle,
        CASE max(pc.niveau_acquis)
            WHEN 1 THEN 5
            WHEN 2 THEN 10
            WHEN 3 THEN 20
            ELSE NULL::integer
        END AS niveau_max_sorts
   FROM personnage_competences pc
     JOIN competences c ON pc.competence_id = c.id
  WHERE c.nom = 'Acquisition de Cercle'::text AND pc.choix_achat IS NOT NULL
  GROUP BY pc.personnage_id, pc.choix_achat;

-- VIEW: vue_competences_maitre_admin
DROP VIEW IF EXISTS public.vue_competences_maitre_admin CASCADE;\nCREATE OR REPLACE VIEW public.vue_competences_maitre_admin AS
 SELECT pc.id,
    COALESCE(p.nom, 'Personnage inconnu'::text) AS personnage_nom,
    COALESCE(pr.nom_affichage, pr.email, 'Joueur inconnu'::text) AS joueur_nom,
    COALESCE(c.nom, 'Compétence inconnue'::text) AS competence_nom,
    pc.niveau_acquis,
    COALESCE(pc.nom_maitre, ''::text) AS nom_maitre,
    COALESCE(pc.statut_maitre, 'non_requis'::text) AS statut_maitre,
    pc.date_acquisition AS date_demande
   FROM personnage_competences pc
     JOIN personnages p ON p.id = pc.personnage_id
     LEFT JOIN profiles pr ON pr.id = p.joueur_id
     LEFT JOIN competences c ON c.id = pc.competence_id
  WHERE est_animateur_ou_admin() AND pc.appris_via_maitre = true;

-- VIEW: vue_competences_maitre_attente
DROP VIEW IF EXISTS public.vue_competences_maitre_attente CASCADE;\nCREATE OR REPLACE VIEW public.vue_competences_maitre_attente AS
 SELECT pc.id,
    pc.niveau_acquis,
    pc.nom_maitre,
    pc.statut_maitre,
    pc.xp_depense,
    pc.personnage_id,
    c.nom AS competence_nom,
    c.description AS competence_description,
    p.nom AS personnage_nom,
    p.niveau AS personnage_niveau,
    pr.nom_affichage AS joueur_nom,
    pr.id AS joueur_id
   FROM personnage_competences pc
     JOIN competences c ON pc.competence_id = c.id
     JOIN personnages p ON pc.personnage_id = p.id
     JOIN profiles pr ON p.joueur_id = pr.id
  WHERE pc.appris_via_maitre = true
  ORDER BY pc.statut_maitre, pr.nom_affichage;

-- VIEW: vue_demandes_races_attente
DROP VIEW IF EXISTS public.vue_demandes_races_attente CASCADE;\nCREATE OR REPLACE VIEW public.vue_demandes_races_attente AS
 SELECT prd.id,
    prd.personnage_id,
    p.nom AS personnage_nom,
    p.niveau AS personnage_niveau,
    p.joueur_id,
    prof.nom_affichage AS joueur_nom,
    prof.email AS joueur_email,
    r.id AS race_id,
    r.nom AS race_nom,
    r.nom_latin AS race_nom_latin,
    prd.background,
    prd.created_at AS date_demande
   FROM personnage_races_demandes prd
     JOIN personnages p ON p.id = prd.personnage_id
     JOIN profiles prof ON prof.id = p.joueur_id
     JOIN races r ON r.id = prd.race_id
  WHERE prd.statut = 'en_attente'::text
  ORDER BY prd.created_at;

-- VIEW: vue_demandes_races_complet
DROP VIEW IF EXISTS public.vue_demandes_races_complet CASCADE;\nCREATE OR REPLACE VIEW public.vue_demandes_races_complet AS
 SELECT prd.id,
    prd.personnage_id,
    p.nom AS personnage_nom,
    p.niveau AS personnage_niveau,
    p.joueur_id,
    prof.nom_affichage AS joueur_nom,
    prof.email AS joueur_email,
    r.id AS race_id,
    r.nom AS race_nom,
    r.nom_latin AS race_nom_latin,
    prd.background,
    prd.statut,
    prd.raison_refus,
    prd.approuve_par,
    approuveur.nom_affichage AS approuve_par_nom,
    prd.created_at AS date_demande,
    prd.date_approbation
   FROM personnage_races_demandes prd
     JOIN personnages p ON p.id = prd.personnage_id
     JOIN profiles prof ON prof.id = p.joueur_id
     JOIN races r ON r.id = prd.race_id
     LEFT JOIN profiles approuveur ON approuveur.id = prd.approuve_par
  ORDER BY prd.created_at DESC;

-- VIEW: vue_domaines_disponibles
DROP VIEW IF EXISTS public.vue_domaines_disponibles CASCADE;\nCREATE OR REPLACE VIEW public.vue_domaines_disponibles AS
 SELECT pc.personnage_id,
    pc.choix_achat AS domaine,
        CASE max(pc.niveau_acquis)
            WHEN 1 THEN 5
            WHEN 2 THEN 10
            WHEN 3 THEN 20
            ELSE NULL::integer
        END AS niveau_max_prieres
   FROM personnage_competences pc
     JOIN competences c ON pc.competence_id = c.id
  WHERE c.nom = 'Acquisition de Domaine'::text AND pc.choix_achat IS NOT NULL
  GROUP BY pc.personnage_id, pc.choix_achat;

-- VIEW: vue_evenements_admin
DROP VIEW IF EXISTS public.vue_evenements_admin CASCADE;\nCREATE OR REPLACE VIEW public.vue_evenements_admin AS
 SELECT e.id,
    e.titre,
    e.description,
    e.date_evenement AS date_debut,
    e.date_fin,
    e.lieu,
    count(i.id)::integer AS nb_participants,
    COALESCE(e.est_publie, false) AS est_publie
   FROM evenements e
     LEFT JOIN inscriptions_evenements i ON i.evenement_id = e.id
  WHERE est_animateur_ou_admin()
  GROUP BY e.id, e.titre, e.description, e.date_evenement, e.date_fin, e.lieu, e.est_publie;

-- VIEW: vue_inscriptions_par_evenement
DROP VIEW IF EXISTS public.vue_inscriptions_par_evenement CASCADE;\nCREATE OR REPLACE VIEW public.vue_inscriptions_par_evenement AS
 SELECT i.id AS inscription_id,
    i.evenement_id,
    i.statut,
    i.xp_attribue,
    i.date_inscription,
    i.date_confirmation,
    e.titre AS evenement_titre,
    e.date_evenement,
    e.type_evenement,
    p.id AS personnage_id,
    p.nom AS personnage_nom,
    p.niveau AS personnage_niveau,
    p.pv_max,
    p.ps_max,
    p.est_mort,
    p.est_actif,
    p.est_verrouille,
    r.nom AS race_nom,
    c.nom AS classe_nom,
    pr.id AS joueur_id,
    pr.nom_affichage AS joueur_nom,
    pr.email AS joueur_email,
    pr.username AS joueur_username
   FROM inscriptions_evenements i
     JOIN evenements e ON e.id = i.evenement_id
     JOIN personnages p ON p.id = i.personnage_id
     JOIN profiles pr ON pr.id = i.joueur_id
     LEFT JOIN races r ON r.id = p.race_id
     LEFT JOIN classes c ON c.id = p.classe_id
  ORDER BY e.date_evenement DESC, pr.nom_affichage;

-- VIEW: vue_inscriptions_resumees
DROP VIEW IF EXISTS public.vue_inscriptions_resumees CASCADE;\nCREATE OR REPLACE VIEW public.vue_inscriptions_resumees AS
 SELECT i.id,
    i.joueur_id,
    i.personnage_id,
    i.evenement_id,
    i.statut,
    i.xp_attribue,
    i.date_inscription,
    e.titre AS evenement_titre,
    e.date_evenement,
    e.date_fin,
    e.lieu,
    e.type_evenement,
    e.xp_recompense,
    e.max_participants,
    p.nom AS personnage_nom,
    pr.nom_affichage AS joueur_nom,
    ( SELECT count(*) AS count
           FROM inscriptions_evenements ie2
          WHERE ie2.evenement_id = i.evenement_id AND ie2.statut = 'present'::text) AS nb_inscrits_confirmes
   FROM inscriptions_evenements i
     JOIN evenements e ON i.evenement_id = e.id
     JOIN personnages p ON i.personnage_id = p.id
     JOIN profiles pr ON i.joueur_id = pr.id;

-- VIEW: vue_joueurs_complete
DROP VIEW IF EXISTS public.vue_joueurs_complete CASCADE;\nCREATE OR REPLACE VIEW public.vue_joueurs_complete AS
 SELECT pr.id AS joueur_id,
    pr.username,
    pr.email,
    pr.nom_affichage,
    pr.role,
    pr.is_active,
    pr.created_at AS compte_cree_le,
    count(p.id) FILTER (WHERE p.est_actif = true AND p.est_mort = false) AS nb_personnages_actifs,
    count(p.id) FILTER (WHERE p.est_mort = true) AS nb_personnages_morts,
    count(p.id) FILTER (WHERE p.est_actif = false) AS nb_personnages_archives,
    count(p.id) AS nb_personnages_total,
    ( SELECT p2.nom
           FROM personnages p2
          WHERE p2.joueur_id = pr.id AND p2.est_actif = true AND p2.est_mort = false
          ORDER BY p2.created_at DESC NULLS LAST
         LIMIT 1) AS personnage_actif_principal
   FROM profiles pr
     LEFT JOIN personnages p ON p.joueur_id = pr.id
  WHERE pr.role = 'joueur'::text
  GROUP BY pr.id, pr.username, pr.email, pr.nom_affichage, pr.role, pr.is_active, pr.created_at
  ORDER BY pr.nom_affichage;

-- VIEW: vue_joueurs_maitres
DROP VIEW IF EXISTS public.vue_joueurs_maitres CASCADE;\nCREATE OR REPLACE VIEW public.vue_joueurs_maitres AS
 SELECT DISTINCT pr.id AS joueur_id,
    pr.nom_affichage AS joueur_nom,
    p.id AS personnage_id,
    p.nom AS personnage_nom,
    r.nom AS race,
    c.nom AS classe,
    p.niveau,
    p.xp_total
   FROM personnage_competences pc
     JOIN personnages p ON pc.personnage_id = p.id
     JOIN profiles pr ON p.joueur_id = pr.id
     JOIN races r ON p.race_id = r.id
     JOIN classes c ON p.classe_id = c.id
  WHERE pc.niveau_acquis = 3 AND (pc.statut_maitre = ANY (ARRAY['non_requis'::text, 'approuve'::text])) AND p.est_actif = true AND p.est_mort = false
  ORDER BY pr.nom_affichage;

-- VIEW: vue_personnage_etat
DROP VIEW IF EXISTS public.vue_personnage_etat CASCADE;\nCREATE OR REPLACE VIEW public.vue_personnage_etat AS
 SELECT p.id AS personnage_id,
    p.joueur_id,
    COALESCE(p.xp_total, 0) - COALESCE(p.xp_depense, 0) AS xp_disponible,
    p.niveau,
    COALESCE(max(
        CASE
            WHEN c.nom = 'Alchimie'::text THEN pc.niveau_acquis
            ELSE NULL::integer
        END), 0) AS niveau_alchimie,
    COALESCE(max(
        CASE
            WHEN c.nom = 'Forge'::text THEN pc.niveau_acquis
            ELSE NULL::integer
        END), 0) AS niveau_forge,
    COALESCE(max(
        CASE
            WHEN c.nom = 'Joaillerie'::text THEN pc.niveau_acquis
            ELSE NULL::integer
        END), 0) AS niveau_joaillerie,
    COALESCE(max(
        CASE
            WHEN c.nom = 'Assemblage de Runes'::text THEN pc.niveau_acquis
            ELSE NULL::integer
        END), 0) AS niveau_runes,
    COALESCE(max(
        CASE
            WHEN c.nom = 'Acquisition de Cercle'::text THEN pc.niveau_acquis
            ELSE NULL::integer
        END), 0) AS niveau_cercle,
    COALESCE(max(
        CASE
            WHEN c.nom = 'Acquisition de Domaine'::text THEN pc.niveau_acquis
            ELSE NULL::integer
        END), 0) AS niveau_domaine,
    COALESCE(bool_or(c.nom = 'Connaissances des Religions'::text AND pc.niveau_acquis >= 1), false) AS a_connaissance_religions,
    COALESCE(bool_or(c.nom = 'Premiers Soins'::text AND pc.niveau_acquis >= 1), false) AS a_premiers_soins,
    COALESCE(bool_or(c.nom = 'Connaissance des Créatures'::text AND pc.niveau_acquis >= 1), false) AS a_connaissance_creatures_1,
    COALESCE(bool_or(c.nom = 'Connaissance des Créatures'::text AND pc.niveau_acquis >= 2), false) AS a_connaissance_creatures_2
   FROM personnages p
     LEFT JOIN personnage_competences pc ON pc.personnage_id = p.id
     LEFT JOIN competences c ON c.id = pc.competence_id
  GROUP BY p.id, p.joueur_id, p.xp_total, p.xp_depense, p.niveau;

-- VIEW: vue_personnages_admin
DROP VIEW IF EXISTS public.vue_personnages_admin CASCADE;\nCREATE OR REPLACE VIEW public.vue_personnages_admin AS
 SELECT p.id,
    p.nom,
    COALESCE(pr.nom_affichage, pr.email, 'Joueur inconnu'::text) AS joueur_nom,
    COALESCE(r.nom, 'Race inconnue'::text) AS race_nom,
    COALESCE(c.nom, 'Classe inconnue'::text) AS classe_nom,
    COALESCE(p.niveau, 1) AS niveau,
    p.est_actif,
    p.etape_creation,
    p.created_at
   FROM personnages p
     LEFT JOIN profiles pr ON pr.id = p.joueur_id
     LEFT JOIN races r ON r.id = p.race_id
     LEFT JOIN classes c ON c.id = p.classe_id
  WHERE est_animateur_ou_admin();

-- VIEW: vue_prochain_evenement
DROP VIEW IF EXISTS public.vue_prochain_evenement CASCADE;\nCREATE OR REPLACE VIEW public.vue_prochain_evenement AS
 SELECT e.id,
    e.titre,
    e.description,
    e.date_evenement,
    e.date_fin,
    e.lieu,
    e.xp_recompense,
    e.max_participants,
    e.type_evenement,
    e.est_publie,
    e.created_by,
    count(i.id) FILTER (WHERE i.statut <> 'annule'::text) AS nb_inscrits,
        CASE
            WHEN e.max_participants IS NULL THEN NULL::bigint
            ELSE e.max_participants - count(i.id) FILTER (WHERE i.statut <> 'annule'::text)
        END AS places_restantes
   FROM evenements e
     LEFT JOIN inscriptions_evenements i ON i.evenement_id = e.id
  WHERE e.est_publie = true AND e.date_evenement > now()
  GROUP BY e.id
  ORDER BY e.date_evenement
 LIMIT 1;

-- VIEW: vue_stats_admin
DROP VIEW IF EXISTS public.vue_stats_admin CASCADE;\nCREATE OR REPLACE VIEW public.vue_stats_admin AS
 SELECT ( SELECT count(*) AS count
           FROM profiles
          WHERE profiles.role = 'joueur'::text) AS nb_joueurs,
    ( SELECT count(*) AS count
           FROM personnages
          WHERE personnages.est_actif = true AND personnages.est_mort = false) AS nb_personnages_actifs,
    ( SELECT count(*) AS count
           FROM inscriptions_evenements
          WHERE inscriptions_evenements.statut = 'en_attente'::text) AS nb_presences_attente,
    ( SELECT count(*) AS count
           FROM personnage_competences
          WHERE personnage_competences.statut_maitre = 'en_attente'::text) AS nb_competences_attente,
    ( SELECT evenements.titre
           FROM evenements
          WHERE evenements.est_publie = true AND evenements.date_evenement > now()
          ORDER BY evenements.date_evenement
         LIMIT 1) AS prochain_evenement_titre,
    ( SELECT evenements.date_evenement
           FROM evenements
          WHERE evenements.est_publie = true AND evenements.date_evenement > now()
          ORDER BY evenements.date_evenement
         LIMIT 1) AS prochain_evenement_date
   FROM ( SELECT 1 AS "?column?"
          WHERE est_animateur_ou_admin()) garde;

-- VIEW: vue_tableau_de_bord
DROP VIEW IF EXISTS public.vue_tableau_de_bord CASCADE;\nCREATE OR REPLACE VIEW public.vue_tableau_de_bord AS
 SELECT p.id,
    p.joueur_id,
    p.nom,
    p.niveau,
    p.xp_total,
    p.xp_depense,
    p.est_mort,
    p.est_actif,
    p.date_creation,
    r.nom AS race_nom,
    c1.nom AS classe_nom,
    c2.nom AS classe_secondaire_nom,
    pr.email AS joueur_email
   FROM personnages p
     LEFT JOIN races r ON p.race_id = r.id
     LEFT JOIN classes c1 ON p.classe_id = c1.id
     LEFT JOIN classes c2 ON p.classe_secondaire_id = c2.id
     LEFT JOIN profiles pr ON p.joueur_id = pr.id;

-- VIEW: vue_traits_par_race
DROP VIEW IF EXISTS public.vue_traits_par_race CASCADE;\nCREATE OR REPLACE VIEW public.vue_traits_par_race AS
 SELECT rt.id AS race_trait_id,
    rt.race_id,
    rt.trait_id,
    rt.sous_type,
    r.nom AS race_nom,
    t.nom AS trait_nom,
    t.description AS trait_description,
    t.cout_xp,
    t.est_actif
   FROM race_traits rt
     JOIN races r ON rt.race_id = r.id
     JOIN traits_raciaux t ON rt.trait_id = t.id
  WHERE t.est_actif = true
  ORDER BY r.nom, rt.sous_type, t.nom;

-- VIEW: vue_verrou_competences
DROP VIEW IF EXISTS public.vue_verrou_competences CASCADE;\nCREATE OR REPLACE VIEW public.vue_verrou_competences AS
 SELECT p.id AS personnage_id,
    COALESCE(bool_or(c.nom = 'Assemblage de Runes'::text), false) AS runes_verrouillees,
    COALESCE(bool_or(c.nom = 'Développement Spirituel'::text), false) AS dev_spirituel_verrouille,
    COALESCE(bool_or(c.nom = 'Développement Spirituel Supérieur'::text), false) AS dev_spirituel_sup_verrouille,
    COALESCE(bool_or(c.nom = 'Canalisation'::text), false) AS canalisation_verrouillee
   FROM personnages p
     LEFT JOIN personnage_competences pc ON pc.personnage_id = p.id
     LEFT JOIN competences c ON c.id = pc.competence_id AND c.verrouillage_croise = true
  GROUP BY p.id;

-- VIEW: vue_xp_personnage
DROP VIEW IF EXISTS public.vue_xp_personnage CASCADE;\nCREATE OR REPLACE VIEW public.vue_xp_personnage AS
 SELECT p.id,
    p.nom,
    p.joueur_id,
    p.xp_total,
    p.xp_depense,
    p.xp_total - p.xp_depense AS xp_disponible,
    p.niveau,
    p.pv_max,
    p.ps_max,
    p.est_actif,
    p.est_mort,
    p.est_verrouille,
    p.etape_creation,
    p.gn_completes,
    p.mini_gn_completes,
    p.ouvertures_terrain,
    r.nom AS race_nom,
    r.nom_latin AS race_latin,
    c.nom AS classe_nom,
    c.pv_depart,
    c.ps_depart,
    rel.nom AS religion_nom,
    fc.nom AS famille_nom,
    pr.nom_affichage AS joueur_nom
   FROM personnages p
     LEFT JOIN races r ON p.race_id = r.id
     LEFT JOIN classes c ON p.classe_id = c.id
     LEFT JOIN religions rel ON p.religion_id = rel.id
     LEFT JOIN familles_criminelles fc ON p.famille_criminelle_id = fc.id
     LEFT JOIN profiles pr ON p.joueur_id = pr.id;

